<?php
$draft=$cycle['status']==='draft';
$manageCycle=$draft&&can('admissions.manage');
$manageSeats=$draft&&can('admission_seats.manage');
$manageForms=$draft&&can('admission_forms.manage');
$manageDocuments=$draft&&can('admission_documents.manage');
$manageFees=$draft&&can('admission_fees.manage');
$optionsText=static function(?string $json):string{$options=json_decode((string)$json,true)?:[];$lines=[];foreach($options as $value=>$label){if(is_int($value))$value=$label;$lines[]=$value.'|'.$label;}return implode("\n",$lines);};
$cycleValue=static fn(string $key,mixed $fallback=''):mixed=>old($key,$fallback);
$sectionNames=[];foreach($sections as $section)$sectionNames[(int)$section['id']]=$section['title'];
$activePrograms=array_values(array_filter($programs,fn(array $program):bool=>$program['status']==='active'&&$program['program_status']==='active'));
$noticeComplete=!$draft||(trim((string)$cycle['name'])!==''&&trim((string)$cycle['code'])!==''&&trim((string)$cycle['slug'])!==''&&trim((string)$cycle['application_number_prefix'])!==''&&trim((string)$cycle['summary'])!==''&&trim((string)$cycle['instructions'])!==''&&trim((string)$cycle['declaration_text'])!==''&&strtotime((string)$cycle['ends_at'])>strtotime((string)$cycle['starts_at'])&&(!$cycle['correction_deadline']||strtotime((string)$cycle['correction_deadline'])>=strtotime((string)$cycle['ends_at'])));
$programmesComplete=count($activePrograms)>0;
$rulesComplete=$programmesComplete&&count(array_filter($activePrograms,fn(array $program):bool=>(int)$program['matrix_total']===(int)$program['seat_capacity']&&count($program['eligibility'])>0))===count($activePrograms);
$feesComplete=$programmesComplete&&count(array_filter($activePrograms,function(array $program):bool{$types=array_unique(array_column(array_filter($program['fees'],fn(array $fee):bool=>$fee['status']==='active'),'fee_type'));return in_array('application_fee',$types,true)&&in_array('admission_fee',$types,true);}))===count($activePrograms);
$formComplete=count($sections)>0&&count(array_filter($fields,fn(array $field):bool=>$field['status']==='active'&&(int)$field['is_required']===1))>0;
$documentsComplete=count(array_filter($requirements,fn(array $requirement):bool=>$requirement['stage']==='application'&&(int)$requirement['is_required']===1))>0;
$setupSteps=[
    ['id'=>'notice','number'=>1,'label'=>'Notice & dates','description'=>'Public admission copy and schedule','complete'=>$noticeComplete],
    ['id'=>'programmes','number'=>2,'label'=>'Programmes','description'=>'Courses and intake defaults','complete'=>$programmesComplete],
    ['id'=>'rules','number'=>3,'label'=>'Seats & eligibility','description'=>'Capacity, categories and rules','complete'=>$rulesComplete],
    ['id'=>'fees','number'=>4,'label'=>'Fees','description'=>'Application and admission charges','complete'=>$feesComplete],
    ['id'=>'form-builder','number'=>5,'label'=>'Application form','description'=>'Sections and applicant fields','complete'=>$formComplete],
    ['id'=>'documents','number'=>6,'label'=>'Documents','description'=>'Required evidence and stages','complete'=>$documentsComplete],
    ['id'=>'review-publish','number'=>7,'label'=>'Review & publish','description'=>'Resolve checks, preview and publish','complete'=>$readiness['ready']],
];
$completedSteps=count(array_filter($setupSteps,fn(array $step):bool=>$step['complete']));
$setupProgress=(int)round(($completedSteps/count($setupSteps))*100);
$firstIncomplete='review-publish';foreach($setupSteps as $step){if(!$step['complete']){$firstIncomplete=$step['id'];break;}}
?>
<div class="page-heading admin-heading"><div><a class="back-link" href="<?= url('admin/admissions') ?>">← Admission cycles</a><span class="eyebrow"><?= e($cycle['code']) ?> · configuration <?= e($cycle['configuration_version']) ?></span><h1><?= e($cycle['name']) ?></h1><p><?= e($cycle['session_name']) ?> · stored <?= e($cycle['status']) ?> · effective <?= e(str_replace('_',' ',$cycle['effective_status'])) ?></p></div><div class="heading-actions"><?php if($draft):?><a class="button button-primary" href="#<?= e($firstIncomplete) ?>">Continue setup →</a><?php endif?><a class="button button-outline" target="_blank" href="<?= url('admin/admissions/'.$cycle['id'].'/preview') ?>">Public preview ↗</a><?php if(in_array($cycle['status'],['published','open'],true)&&can('admissions.manage')):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/close') ?>"><?= csrf_field() ?><button class="button button-outline" data-confirm="Close this cycle to new applications?">Close cycle</button></form><?php elseif($cycle['status']==='closed'&&can('admissions.manage')):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/archive') ?>"><?= csrf_field() ?><button class="button button-outline" data-confirm="Archive this closed cycle?">Archive cycle</button></form><?php endif?></div></div>

<section class="card admission-setup-hero"><div><span class="eyebrow">Publication readiness · guided wizard</span><h2>Complete the admission notice in seven focused steps</h2><p>Work through one panel at a time. Your draft stays editable until the final publication step creates an immutable public version.</p></div><div class="setup-progress-summary"><b><?= $setupProgress ?>%</b><span><?= $completedSteps ?>/<?= count($setupSteps) ?> steps complete</span><div class="setup-progress-track"><i style="--progress:<?= $setupProgress ?>%"></i></div></div></section>

<div class="admission-sliding-workspace admission-wizard" data-section-workspace>
<nav class="admission-workspace-nav admission-stepper" data-section-tabs aria-label="Admission notice setup steps"><?php foreach($setupSteps as $step):?><a href="#<?= e($step['id']) ?>" class="<?= $step['complete']?'is-complete':'is-pending' ?>" data-section-aliases="<?= $step['id']==='programmes'?'programme-':($step['id']==='rules'?'seats-,eligibility-':($step['id']==='fees'?'fees-':'')) ?>"><i><?= $step['complete']?'✓':(int)$step['number'] ?></i><span><b><?= e($step['label']) ?></b><small><?= e($step['description']) ?></small></span></a><?php endforeach?></nav>

<section class="card settings-panel wizard-panel" id="notice" data-section-panel><div class="card-heading"><div><span class="eyebrow">Step 1</span><h2>Cycle identity, dates and applicant copy</h2></div><span class="status-pill status-<?= e($cycle['status']) ?>"><?= e(ucfirst($cycle['status'])) ?></span></div><?php if($manageCycle):?><form method="post" action="<?= url('admin/admissions/'.$cycle['id']) ?>" enctype="multipart/form-data"><?= csrf_field() ?><div class="form-grid three"><label><span>Academic session</span><select name="academic_session_id" required><?php foreach($sessions as $session):?><option value="<?= e($session['id']) ?>"<?= selected($cycleValue('academic_session_id',$cycle['academic_session_id']),$session['id']) ?>><?= e($session['name']) ?></option><?php endforeach?></select></label><label><span>Cycle name</span><input name="name" value="<?= e($cycleValue('name',$cycle['name'])) ?>" required></label><label><span>Cycle code</span><input name="code" value="<?= e($cycleValue('code',$cycle['code'])) ?>" required></label><label><span>Public slug</span><input name="slug" value="<?= e($cycleValue('slug',$cycle['slug'])) ?>" required></label><label><span>Applications open</span><input type="datetime-local" name="starts_at" value="<?= e($cycleValue('starts_at',date('Y-m-d\TH:i',strtotime($cycle['starts_at'])))) ?>" required></label><label><span>Applications close</span><input type="datetime-local" name="ends_at" value="<?= e($cycleValue('ends_at',date('Y-m-d\TH:i',strtotime($cycle['ends_at'])))) ?>" required></label><label><span>Correction deadline</span><input type="datetime-local" name="correction_deadline" value="<?= e($cycleValue('correction_deadline',$cycle['correction_deadline']?date('Y-m-d\TH:i',strtotime($cycle['correction_deadline'])):'')) ?>"></label><label><span>Application number prefix</span><input name="application_number_prefix" value="<?= e($cycleValue('application_number_prefix',$cycle['application_number_prefix'])) ?>" required></label><label><span>Maximum preferences</span><input type="number" min="1" max="10" name="max_program_preferences" value="<?= e($cycleValue('max_program_preferences',$cycle['max_program_preferences'])) ?>"></label><label><span>Closing-soon threshold (hours)</span><input type="number" min="0" max="720" name="closing_soon_hours" value="<?= e($cycleValue('closing_soon_hours',$cycle['closing_soon_hours'])) ?>"></label><label class="full"><span>Public admission summary *</span><textarea name="summary" rows="3" required><?= e($cycleValue('summary',$cycle['summary'])) ?></textarea></label><label class="full"><span>Applicant instructions *</span><textarea name="instructions" rows="4" required><?= e($cycleValue('instructions',$cycle['instructions'])) ?></textarea></label><label class="full"><span>Applicant declaration *</span><textarea name="declaration_text" rows="3" required><?= e($cycleValue('declaration_text',$cycle['declaration_text'])) ?></textarea></label><label class="full"><span>Prospectus PDF (maximum 10 MB)</span><input type="file" name="prospectus" accept="application/pdf"><small><?= $cycle['prospectus_original_name']?'Current: '.e($cycle['prospectus_original_name']):'No prospectus uploaded' ?></small></label></div><div class="wizard-panel-actions"><a class="button button-outline" href="<?= url('admin/admissions') ?>">Exit setup</a><div><button class="button button-outline" name="continue_to" value="notice">Save draft</button><button class="button button-primary" name="continue_to" value="programmes">Save & continue: Programmes →</button></div></div></form><?php else:?><div class="immutable-notice"><b>Published configuration is read-only.</b><p>Applications remain bound to version <?= e($cycle['configuration_version']) ?>. Duplicate the cycle to make a separately versioned draft.</p></div><?php endif?></section>

