'].'/delete') ?>"><?= csrf_field() ?><span><?= e($seat['category'].' · '.$seat['quota']) ?></span><button class="text-button danger" data-confirm="Remove this empty seat row and recalculate programme capacity?">Remove row</button></form><?php endif; endforeach?><?php else:?><div class="table-wrap"><table><thead><tr><th>Category</th><th>Quota</th><th>Seats</th><th>Allocated</th></tr></thead><tbody><?php foreach($program['seats'] as $seat):?><tr><td><?= e($seat['category']) ?></td><td><?= e($seat['quota']) ?></td><td><?= e($seat['seats']) ?></td><td><?= e($seat['filled_seats']) ?></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>

