ked($rule['is_blocking']) ?>><span>Blocking rule</span></label><label class="full"><span>Applicant/reviewer message</span><input name="message" value="<?= e($rule['message']) ?>" required></label></div><div class="record-actions"><button class="button button-outline">Update rule</button></div></form><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/eligibility/'.$rule['id'].'/delete') ?>"><?= csrf_field() ?><button class="text-button danger" data-confirm="Delete this eligibility rule?">Delete rule</button></form><?php endif?></details><?php endforeach?></div><?php if(!$program['eligibility']):?><div class="empty-inline">No eligibility rule configured.</div><?php endif?><?php if($manageCycle):?><details class="inline-builder" <?= !$program['eligibility']?'open':'' ?>><summary>+ Add eligibility rule</summary><form method="post" action="<?= url('admin/admissions/'.$cycle['id'].'/programs/'.$program['id'].'/eligibility') ?>"><?= csrf_field() ?><div class="form-grid three"><label><span>Rule type</span><select name="rule_type"><?php foreach(['marks','subject','age','category','entrance','custom'] as $value):?><option value="<?= e($value) ?>"><?= e(ucfirst($value)) ?></option><?php endforeach?></select></label><label><span>Field key</span><input name="field_name" required placeholder="class_12_percentage"></label><label><span>Operator</span><select name="operator"><?php foreach(['eq','neq','gt','gte','lt','lte','in','not_in','contains','between','regex'] as $value):?><option value="<?= e($value) ?>"><?= e($value) ?></option><?php endforeach?></select></label><label><span>Comparison value</span><input name="comparison_value" required></label><label><span>Sort order</span><input type="number" name="sort_order" value="100"></label><label class="check-control"><input type="checkbox" name="is_blocking" value="1"><span>Blocking rule</span></label><label class="full"><span>Message</span><input name="message" required></label></div>